// Exact decimal values — the subset of Python's `decimal.Decimal` that the
// money formatting path actually exercises.
//
// A finite value is `(-1)**sign * digits * 10**exp`, where `digits` is a string
// of ASCII digits with no leading zeros (except the single-digit "0").  Specials
// carry a `special` tag instead of a coefficient.
//
// Everything here is plain string/array digit manipulation: no BigInt, no
// floating point, so the arithmetic is exact at any magnitude.

/** Default precision of Python's decimal context (`getcontext().prec`). */
export const CONTEXT_PRECISION = 28;

const DECIMAL_RE = /^([+-]?)(\d*)(?:\.(\d*))?(?:[eE]([+-]?\d+))?$/;
const SPECIAL_RE = /^([+-]?)(?:(inf(?:inity)?)|(s?nan\d*))$/i;

/** Strip leading zeros, keeping at least one digit. */
function trimLeadingZeros(digits) {
  let i = 0;
  while (i < digits.length - 1 && digits[i] === '0') i++;
  return digits.slice(i);
}

/** Add one to a non-negative decimal digit string (may grow by one digit). */
function incrementDigits(digits) {
  const out = digits.split('');
  let i = out.length - 1;
  for (; i >= 0; i--) {
    if (out[i] === '9') {
      out[i] = '0';
    } else {
      out[i] = String.charCodeAt ? String.fromCharCode(out[i].charCodeAt(0) + 1) : out[i];
      break;
    }
  }
  return i < 0 ? '1' + out.join('') : out.join('');
}

export class Decimal {
  /**
   * @param {0|1} sign     1 when the value carries a minus sign (including -0).
   * @param {string} digits Coefficient digits; "0" for zero, "" for specials.
   * @param {number} exp    Power-of-ten exponent applied to `digits`.
   * @param {null|'nan'|'inf'} special
   */
  constructor(sign, digits, exp, special = null) {
    this.sign = sign;
    this.digits = digits;
    this.exp = exp;
    this.special = special;
  }

  /**
   * Parse a decimal literal the way `decimal.Decimal(str)` does.
   * Accepts plain, scientific, and special ("nan"/"inf"/"infinity") forms.
   */
  static fromString(text) {
    const s = String(text).trim();

    const special = SPECIAL_RE.exec(s);
    if (special) {
      const sign = special[1] === '-' ? 1 : 0;
      // Python renders NaN without a sign, but Decimal itself keeps one; the
      // distinction never reaches output because `abs()` runs first.
      return new Decimal(sign, '', 0, special[2] ? 'inf' : 'nan');
    }

    const m = DECIMAL_RE.exec(s);
    if (!m || (m[2] === '' && (m[3] === undefined || m[3] === ''))) {
      throw new Error(`invalid decimal literal: ${s}`);
    }
    const sign = m[1] === '-' ? 1 : 0;
    const intPart = m[2] || '';
    const fracPart = m[3] || '';
    const expPart = m[4] ? parseInt(m[4], 10) : 0;

    const digits = trimLeadingZeros(intPart + fracPart) || '0';
    return new Decimal(sign, digits, expPart - fracPart.length);
  }

  isNaN() {
    return this.special === 'nan';
  }

  isInfinite() {
    return this.special === 'inf';
  }

  isFinite() {
    return this.special === null;
  }

  /** Mirrors `Decimal.is_signed()`: true for -0 as well as ordinary negatives. */
  isSigned() {
    return this.sign === 1;
  }

  isZero() {
    return this.special === null && this.digits === '0';
  }

  /** `abs(value)` — drops the sign, keeps everything else. */
  abs() {
    return new Decimal(0, this.digits, this.exp, this.special);
  }

  /**
   * Round to exactly `places` digits after the decimal point using
   * ROUND_HALF_EVEN, the default rounding of Python's decimal context.
   *
   * Returns `{ digits, overflow }` where `digits` is the resulting coefficient
   * (already scaled by 10**places) and `overflow` reports whether the result
   * would exceed the context precision — the caller decides how to signal it.
   */
  roundToPlaces(places) {
    const shift = this.exp + places;
    let coefficient;

    if (shift >= 0) {
      // Widening: the value is exactly representable, just pad with zeros.
      coefficient = this.digits === '0' ? '0' : this.digits + '0'.repeat(shift);
    } else {
      const drop = -shift;
      let kept;
      let dropped;
      if (drop >= this.digits.length) {
        kept = '';
        dropped = '0'.repeat(drop - this.digits.length) + this.digits;
      } else {
        kept = this.digits.slice(0, this.digits.length - drop);
        dropped = this.digits.slice(this.digits.length - drop);
      }

      const first = dropped.charCodeAt(0) - 48;
      const restNonZero = /[1-9]/.test(dropped.slice(1));
      const lastKept = kept === '' ? 0 : kept.charCodeAt(kept.length - 1) - 48;

      let roundUp;
      if (first > 5) roundUp = true;
      else if (first < 5) roundUp = false;
      else if (restNonZero) roundUp = true;
      else roundUp = lastKept % 2 === 1; // exact tie -> round to even

      coefficient = kept === '' ? '0' : kept;
      if (roundUp) coefficient = incrementDigits(coefficient);
    }

    coefficient = trimLeadingZeros(coefficient);
    return { digits: coefficient, overflow: coefficient.length > CONTEXT_PRECISION };
  }

  /**
   * Split a finite value rounded to `places` decimals into printable pieces,
   * as `f"{value:f}"` followed by `partition('.')` would.
   */
  toFixedParts(places) {
    const { digits } = this.roundToPlaces(places);
    const padded = digits.padStart(places + 1, '0');
    const cut = padded.length - places;
    return { intPart: padded.slice(0, cut), fracPart: places > 0 ? padded.slice(cut) : '' };
  }
}

