// Python's `float(str)` and `str(float)` semantics.
//
// Both directions matter: argparse converts `--amount` with `float()`, and
// `Money.__init__` then rebuilds an exact decimal from `str(amount)` — so the
// digits Python's repr would have produced are what actually get formatted.

/**
 * Value of a Unicode decimal digit, or -1.
 *
 * Python's float parser runs the input through
 * `PyUnicode_TransformDecimalAndSpaceToASCII`, so any Nd codepoint counts as a
 * digit.  Nd blocks are contiguous runs of ten starting at their zero, which
 * lets us recover the value without carrying a lookup table.
 */
function unicodeDigitValue(ch) {
  if (ch >= '0' && ch <= '9') return ch.charCodeAt(0) - 48;
  if (!/^\p{Nd}$/u.test(ch)) return -1;
  const code = ch.codePointAt(0);
  for (let k = 0; k <= 9; k++) {
    const zero = code - k;
    if (!/^\p{Nd}$/u.test(String.fromCodePoint(zero))) break;
    if (zero === 0 || !/^\p{Nd}$/u.test(String.fromCodePoint(zero - 1))) return k;
  }
  return -1;
}

/** Fold Unicode digits and Unicode spaces down to ASCII, as CPython does. */
function transformDecimalAndSpaceToAscii(text) {
  let out = '';
  for (const ch of text) {
    const value = unicodeDigitValue(ch);
    if (value >= 0) {
      out += String(value);
    } else if (/^\s$/u.test(ch) || ch === ' ' || ch === ' ' || ch === '᠎') {
      out += ' ';
    } else {
      out += ch;
    }
  }
  return out;
}

/**
 * Remove PEP 515 digit-group underscores, rejecting misplaced ones.
 * Underscores are legal only between two digits.
 * @returns {string|null} the cleaned string, or null if invalid.
 */
function stripUnderscores(text) {
  if (!text.includes('_')) return text;
  for (let i = 0; i < text.length; i++) {
    if (text[i] !== '_') continue;
    const prev = text[i - 1];
    const next = text[i + 1];
    const isDigit = (c) => c !== undefined && c >= '0' && c <= '9';
    if (!isDigit(prev) || !isDigit(next)) return null;
  }
  return text.split('_').join('');
}

const FLOAT_RE = /^[+-]?(?:\d+(?:\.\d*)?|\.\d+)(?:[eE][+-]?\d+)?$/;
const FLOAT_SPECIAL_RE = /^([+-]?)(?:(inf(?:inity)?)|(nan))$/i;

/**
 * Parse a string exactly as Python's `float()` does.
 * @returns {{ok: true, value: number}|{ok: false}}
 */
export function pyFloat(text) {
  const folded = transformDecimalAndSpaceToAscii(String(text)).trim();
  const cleaned = stripUnderscores(folded);
  if (cleaned === null || cleaned === '') return { ok: false };

  const special = FLOAT_SPECIAL_RE.exec(cleaned);
  if (special) {
    const negative = special[1] === '-';
    if (special[2]) return { ok: true, value: negative ? -Infinity : Infinity };
    return { ok: true, value: NaN }; // Python keeps a sign bit here, repr hides it
  }

  if (!FLOAT_RE.test(cleaned)) return { ok: false };
  return { ok: true, value: Number(cleaned) };
}

/**
 * Python's `str(float)` / `repr(float)`.
 *
 * Only the digits matter downstream (an exact decimal is rebuilt from them),
 * and both CPython and ECMAScript emit the shortest round-tripping decimal — so
 * `Number.prototype.toString` supplies the same significant digits.  The two
 * places JS diverges are the sign of negative zero and the spelling of the
 * specials, which is what this function fixes up.
 */
export function pyFloatRepr(value) {
  if (Number.isNaN(value)) return 'nan'; // Python never shows NaN's sign
  if (value === Infinity) return 'inf';
  if (value === -Infinity) return '-inf';
  if (value === 0) return Object.is(value, -0) ? '-0.0' : '0.0';
  return value.toString();
}

/**
 * Python's `repr()` for a `str`, used verbatim in argparse error messages.
 * Prefers single quotes, switches to double quotes when the value contains a
 * single quote but no double quote.
 */
export function pyReprStr(text) {
  const s = String(text);
  const quote = s.includes("'") && !s.includes('"') ? '"' : "'";
  let out = quote;
  for (const ch of s) {
    const code = ch.codePointAt(0);
    if (ch === '\\') out += '\\\\';
    else if (ch === quote) out += '\\' + ch;
    else if (ch === '\n') out += '\\n';
    else if (ch === '\r') out += '\\r';
    else if (ch === '\t') out += '\\t';
    else if (code < 0x20 || code === 0x7f) out += '\\x' + code.toString(16).padStart(2, '0');
    else out += ch;
  }
  return out + quote;
}

