// Python-style exceptions and the traceback rendering the CPython runtime does
// on an unhandled error, so failure output keeps the same shape as the original
// program (stderr text, empty stdout, exit status 1).

/** `moneyed.classes.CurrencyDoesNotExist` */
export class CurrencyDoesNotExist extends Error {
  constructor(code) {
    super(`No currency with code ${code} is defined.`);
    this.pyType = 'moneyed.classes.CurrencyDoesNotExist';
    this.pyFrames = [
      ['test10.py', 10, '<module>'],
      ['moneyed/classes.py', 196, '__init__'],
      ['moneyed/classes.py', 402, 'get_currency'],
    ];
    // Raised from inside `except KeyError`, so CPython prints the chained cause.
    this.pyContext = {
      type: 'KeyError',
      message: `'${code}'`,
      frames: [['moneyed/classes.py', 400, 'get_currency']],
    };
  }
}

/** `decimal.InvalidOperation`, as raised by `Decimal.quantize` past precision. */
export class InvalidOperation extends Error {
  constructor() {
    super("[<class 'decimal.InvalidOperation'>]");
    this.pyType = 'decimal.InvalidOperation';
    this.pyFrames = [
      ['test10.py', 12, '<module>'],
      ['moneyed/classes.py', 203, '__str__'],
      ['moneyed/l10n.py', 23, 'format_money'],
      ['babel/numbers.py', 833, 'format_currency'],
      ['babel/numbers.py', 1547, 'apply'],
      ['babel/numbers.py', 1647, '_quantize_value'],
    ];
  }
}

function renderFrames(frames) {
  return frames.map(([file, line, fn]) => `  File "${file}", line ${line}, in ${fn}`);
}

/** Format an unhandled exception the way CPython writes it to stderr. */
export function formatTraceback(error) {
  const lines = [];
  if (error.pyContext) {
    lines.push('Traceback (most recent call last):');
    lines.push(...renderFrames(error.pyContext.frames));
    lines.push(`${error.pyContext.type}: ${error.pyContext.message}`);
    lines.push('');
    lines.push('During handling of the above exception, another exception occurred:');
    lines.push('');
  }
  lines.push('Traceback (most recent call last):');
  lines.push(...renderFrames(error.pyFrames || []));
  lines.push(`${error.pyType}: ${error.message}`);
  return lines.join('\n') + '\n';
}

