// A faithful reimplementation of the slice of Python's `argparse` that this
// program uses: two required value-taking long options plus the automatic
// `-h/--help`.  Error wording, stream choice and exit codes all follow CPython.

import { pyReprStr } from './floats.mjs';

/**
 * argparse's `_negative_number_matcher`.  Because none of the options look like
 * negative numbers, a token matching this is treated as a value rather than as
 * an unknown option — which is why `--amount -5` works but `--amount -5e3`
 * reports "expected one argument".
 */
const NEGATIVE_NUMBER_RE = /^-\d+$|^-\d*\.\d+$/;

/** Raised for anything that makes argparse call `parser.error()` (exit code 2). */
export class ArgumentParserError extends Error {}

class HelpRequested extends Error {}

export class ArgumentParser {
  /**
   * @param {string} prog Program name used in usage and error lines.  Defaults
   *   to the reference build's name so diagnostics match it byte for byte.
   */
  constructor(prog = 'test10_executable') {
    this.prog = prog;
    this.actions = [
      { flags: ['-h', '--help'], kind: 'help', help: 'show this help message and exit' },
    ];
  }

  /** Mirrors `parser.add_argument('--name', type=..., required=True)`. */
  addArgument(flag, { type = (v) => v, required = false, metavar = null } = {}) {
    const dest = flag.replace(/^--/, '').replace(/-/g, '_');
    this.actions.push({
      flags: [flag],
      kind: 'store',
      dest,
      type,
      required,
      metavar: metavar || dest.toUpperCase(),
      help: null,
    });
    return this;
  }

  formatUsage() {
    const parts = this.actions.map((a) =>
      a.kind === 'help' ? '[-h]' : `${a.flags[0]} ${a.metavar}`
    );
    return `usage: ${this.prog} ${parts.join(' ')}\n`;
  }

  formatHelp() {
    const invocations = this.actions.map((a) =>
      a.kind === 'help' ? a.flags.join(', ') : `${a.flags[0]} ${a.metavar}`
    );
    // HelpFormatter: help text starts at min(longest invocation + indent + 2, 24).
    const actionMaxLength = Math.max(...invocations.map((s) => s.length + 2));
    const helpPosition = Math.min(actionMaxLength + 2, 24);

    let out = this.formatUsage() + '\noptions:\n';
    this.actions.forEach((action, i) => {
      const invocation = '  ' + invocations[i];
      if (!action.help) {
        out += invocation + '\n';
      } else if (invocation.length <= helpPosition - 2) {
        out += invocation.padEnd(helpPosition) + action.help + '\n';
      } else {
        out += invocation + '\n' + ' '.repeat(helpPosition) + action.help + '\n';
      }
    });
    return out;
  }

  error(message) {
    throw new ArgumentParserError(message);
  }

  /** Resolve a token to an action, honouring unique-prefix abbreviations. */
  #lookupOption(name) {
    const exact = this.actions.find((a) => a.flags.includes(name));
    if (exact) return exact;
    if (!name.startsWith('--')) return null;
    const matches = this.actions.filter((a) => a.flags.some((f) => f.startsWith(name)));
    if (matches.length === 1) return matches[0];
    if (matches.length > 1) {
      const options = matches.flatMap((a) => a.flags.filter((f) => f.startsWith(name)));
      this.error(`ambiguous option: ${name} could match ${options.join(', ')}`);
    }
    return null;
  }

  /** argparse's `_parse_optional`: decide whether a token introduces an option. */
  #isOptionToken(token) {
    if (!token.startsWith('-')) return false;
    if (token === '-' || token === '--') return true;
    if (NEGATIVE_NUMBER_RE.test(token)) return false;
    if (token.includes(' ')) return false;
    return true;
  }

  /**
   * @returns {{help: true}|{help: false, values: object}}
   * @throws {ArgumentParserError}
   */
  parseArgs(argv) {
    const values = Object.create(null);
    const seen = new Set();
    const extras = [];
    let onlyPositional = false;

    for (let i = 0; i < argv.length; i++) {
      const token = argv[i];

      if (onlyPositional || !this.#isOptionToken(token)) {
        extras.push(token);
        continue;
      }
      if (token === '--') {
        onlyPositional = true;
        continue;
      }

      const eq = token.indexOf('=');
      const name = eq === -1 ? token : token.slice(0, eq);
      const attached = eq === -1 ? null : token.slice(eq + 1);

      const action = this.#lookupOption(name);
      if (!action) {
        extras.push(token);
        continue;
      }

      if (action.kind === 'help') throw new HelpRequested();

      let raw = attached;
      if (raw === null) {
        const next = argv[i + 1];
        if (next === undefined || this.#isOptionToken(next)) {
          this.error(`argument ${action.flags[0]}: expected one argument`);
        }
        raw = next;
        i++;
      }

      let converted;
      try {
        converted = action.type(raw);
      } catch {
        this.error(`argument ${action.flags[0]}: invalid ${action.typeName} value: ${pyReprStr(raw)}`);
      }
      values[action.dest] = converted;
      seen.add(action.dest);
    }

    const missing = this.actions
      .filter((a) => a.kind === 'store' && a.required && !seen.has(a.dest))
      .map((a) => a.flags[0]);
    if (missing.length) {
      this.error(`the following arguments are required: ${missing.join(', ')}`);
    }
    if (extras.length) {
      this.error(`unrecognized arguments: ${extras.join(' ')}`);
    }

    return { help: false, values };
  }

  /** True when the thrown error came from `-h`/`--help`. */
  static isHelpRequest(error) {
    return error instanceof HelpRequested;
  }
}

