// A port of `babel.numbers.NumberPattern` restricted to the non-scientific,
// non-significant-digits path that currency formatting takes.
//
// The structure deliberately tracks babel's: `_format_int` does the grouping,
// `_format_frac` the fraction, `_quantize_value` the rounding, and `apply`
// glues the affixes on.  Keeping the shapes aligned is what makes the edge
// cases (NaN, infinity, negative zero) fall out for free rather than needing
// special cases bolted on.

import { Decimal } from '../decimal/core.mjs';
import { InvalidOperation } from '../python/errors.mjs';
import {
  DECIMAL_SYMBOL,
  GROUP_SYMBOL,
  INFINITY_SYMBOL,
  MINUS_SIGN,
} from '../cldr/en-us.mjs';

/**
 * Split a CLDR pattern into affixes, grouping sizes and integer precision.
 * Only the subset needed here is handled: an optional `;`-separated negative
 * subpattern, `#`/`0`/`,`/`.` in the number part, everything else literal.
 */
export function parsePattern(pattern) {
  const [positive, negative] = pattern.split(';');

  const dissect = (sub) => {
    const match = /^([^#0]*)([#0,.]+)([^#0]*)$/.exec(sub);
    if (!match) throw new Error(`unsupported number pattern: ${sub}`);
    return { prefix: match[1], number: match[2], suffix: match[3] };
  };

  const pos = dissect(positive);
  // With no explicit negative subpattern, CLDR prepends the minus sign.
  const neg = negative ? dissect(negative) : { ...pos, prefix: MINUS_SIGN + pos.prefix };

  const [integer, fraction = ''] = pos.number.split('.');
  const groups = integer.split(',');
  // Primary group is the last run of digit placeholders, secondary the one
  // before it (both 3 for `#,##0.00`; babel falls back to primary when absent).
  const primary = groups.length > 1 ? groups[groups.length - 1].length : Infinity;
  const secondary = groups.length > 2 ? groups[groups.length - 2].length : primary;

  return {
    pattern,
    prefix: [pos.prefix, neg.prefix],
    suffix: [pos.suffix, neg.suffix],
    numberPattern: pos.number,
    grouping: [primary, secondary],
    intPrec: [(integer.match(/0/g) || []).length, integer.length],
    fracPrec: [
      (fraction.match(/0/g) || []).length,
      fraction.length,
    ],
  };
}

/** `NumberPattern._format_int` — left-pad to the minimum width, then group. */
function formatInt(value, minWidth, grouping) {
  let head = value.length < minWidth ? '0'.repeat(minWidth - value.length) + value : value;
  let size = grouping[0];
  let tail = '';
  while (head.length > size) {
    tail = GROUP_SYMBOL + head.slice(head.length - size) + tail;
    head = head.slice(0, head.length - size);
    size = grouping[1];
  }
  return head + tail;
}

/** `NumberPattern._format_frac` — pad, drop entirely when the max is zero. */
function formatFrac(value, [min, max]) {
  let digits = value.length < min ? value + '0'.repeat(min - value.length) : value;
  if (max === 0 || (min === 0 && Number(digits) === 0)) return '';
  while (digits.length > min && digits.endsWith('0')) digits = digits.slice(0, -1);
  return DECIMAL_SYMBOL + digits;
}

