// `babel.numbers.format_currency` for the `en_US` locale.

import { getCurrencyPrecision } from '../cldr/currency-digits.mjs';
import { getCurrencySymbol } from '../cldr/currency-symbols.mjs';
import { CURRENCY_PATTERN } from '../cldr/en-us.mjs';
import { applyPattern, parsePattern, toDecimal } from './number-pattern.mjs';

const STANDARD_CURRENCY_PATTERN = parsePattern(CURRENCY_PATTERN);

/**
 * Format an amount as currency.
 *
 * @param {import('../decimal/core.mjs').Decimal|string|number} number
 * @param {string} currencyCode Uppercase ISO code.
 * @param {{currencyDigits?: boolean}} [options]
 */
export function formatCurrency(number, currencyCode, { currencyDigits = true } = {}) {
  const value = toDecimal(number);
  const digits = currencyDigits
    ? getCurrencyPrecision(currencyCode)
    : STANDARD_CURRENCY_PATTERN.fracPrec[1];

  return applyPattern(
    STANDARD_CURRENCY_PATTERN,
    value,
    { code: currencyCode, digits },
    getCurrencySymbol
  );
}

