// `moneyed.classes` — the Currency/Money pair, reduced to what this program uses.

import { Decimal } from '../decimal/core.mjs';
import { CurrencyDoesNotExist } from '../python/errors.mjs';
import { pyFloatRepr } from '../python/floats.mjs';
import { formatMoney } from './l10n.mjs';
import { hasCurrency } from './currencies.mjs';

export class Currency {
  constructor(code) {
    this.code = code;
  }
}

/**
 * `moneyed.get_currency(code)`.
 * @throws {CurrencyDoesNotExist} with the *uppercased* code, matching the
 *   KeyError that py-moneyed wraps.
 */
export function getCurrency(code) {
  if (!hasCurrency(code)) throw new CurrencyDoesNotExist(code);
  return new Currency(code);
}

export class Money {
  /**
   * @param {number|string|Decimal} amount Anything non-Decimal goes through
   *   `Decimal(str(amount))`, so a float contributes exactly the digits of its
   *   `repr` — not the full binary expansion.  That is what makes ties like
   *   0.015 round as an exact decimal half.
   * @param {string} currency Case-insensitive; upper-cased before lookup.
   */
  constructor(amount, currency) {
    this.amount =
      amount instanceof Decimal
        ? amount
        : Decimal.fromString(typeof amount === 'number' ? pyFloatRepr(amount) : String(amount));
    this.currency = currency instanceof Currency ? currency : getCurrency(String(currency).toUpperCase());
  }

  /** `Money.__str__` */
  toString() {
    return formatMoney(this);
  }
}

