import process from 'node:process';

import { ArgumentParser, ArgumentParserError } from './lib/python/argparse.mjs';
import { formatTraceback } from './lib/python/errors.mjs';
import { pyFloat } from './lib/python/floats.mjs';
import { Money } from './lib/moneyed/classes.mjs';

const parser = new ArgumentParser();
parser.addArgument('--amount', {
  required: true,
  typeName: 'float',
  type: (raw) => {
    const parsed = pyFloat(raw);
    if (!parsed.ok) throw new Error('not a float');
    return parsed.value;
  },
});
parser.addArgument('--currency', { required: true, typeName: 'str' });

let args;
try {
  args = parser.parseArgs(process.argv.slice(2)).values;
} catch (error) {
  if (ArgumentParser.isHelpRequest(error)) {
    process.stdout.write(parser.formatHelp());
    process.exit(0);
  }
  if (error instanceof ArgumentParserError) {
    // argparse writes usage plus a one-line diagnostic to stderr, then exits 2.
    process.stderr.write(`${parser.formatUsage()}${parser.prog}: error: ${error.message}\n`);
    process.exit(2);
  }
  throw error;
}

try {
  const m = new Money(args.amount, args.currency);
  process.stdout.write(String(m) + '\n');
} catch (error) {
  if (!error.pyType) throw error;
  // Reproduce CPython's unhandled-exception report, including the PyInstaller
  // bootloader's trailing line that the reference binary emits.
  process.stderr.write(formatTraceback(error));
  process.stderr.write(
    `[PYI-${process.pid}:ERROR] Failed to execute script 'test10' due to unhandled exception!\n`
  );
  process.exit(1);
}

